@push('scripts')<script>const f=document.querySelector('#photo-input'),p=document.querySelector('#photo-preview');if(f)f.addEventListener('change',()=>{if(f.files[0]){p.innerHTML='';const i=document.createElement('img');i.src=URL.createObjectURL(f.files[0]);p.append(i)}});const dt=document.querySelector('.document-toggle'),df=document.querySelector('.document-choices'),flag=document.querySelector('[name="show_documents"]');dt?.addEventListener('click',()=>{const opening=df.classList.contains('hidden');df.classList.toggle('hidden');dt.setAttribute('aria-expanded',String(opening));flag.value=opening?'1':''});</script>@endpush
